"use strict";

// ===========================================================================
// Dicas progressivas: cada sistema novo explica a si mesmo uma única vez, no momento em que a pessoa chega nele (nada de tutorial gigante),
// e o menu Missões → Hoje sugere o próximo passo (só sugestões de coisas que ainda não foram vistas).
// Usa o mesmo cartão do Tutor (Tutor.topic), com texto embutido. Só com as dicas ligadas (Opções → Dicas). Estado: state.tuts[id].
// Gatilhos: abrir certos modais/telas (automático, por Tips.watch) e chamadas Tips.fire(id) nos próprios sistemas.
// ===========================================================================
const Tips = (function () {
  const L = window.L;
  const pick = (v) => I18N.pick(v);
  // id → { t, x, modal?, screen?, target?, sug?: { when(): bool, do: L } }
  const TIPS = {
    aquario: { modal: "aq-modal", t: L("Aquário", "Aquarium", "Acuario"), x: L("Cuide das criaturas (comida, água, luz), pesque no cais da praia e na fenda do fundo do mar e veja cada espécie em 3D. Um aquário saudável rende bônus.", "Look after the creatures (food, water, light), fish at the beach pier and the undersea rift and see each species in 3D. A healthy aquarium pays bonuses.", "Cuida de las criaturas (comida, agua, luz), pesca en el muelle de la playa y en la grieta submarina y mira cada especie en 3D. Un acuario sano da bonos."), sug: { when: () => Boolean(state.owned && state.owned.aquario), do: L("Alimente o aquário hoje.", "Feed the aquarium today.", "Alimenta el acuario hoy.") } },
    investigar: { modal: "invest-modal", t: L("Perguntar", "Ask", "Preguntar"), x: L("São 12 áreas da vida da pessoa, 3 perguntas por consulta. Cada uma gasta tempo, e as áreas delicadas (🔒) só abrem com vínculo. Perguntar não gasta afinidade: pergunte sem medo.", "Twelve areas of the person's life, 3 questions per session. Each costs time, and sensitive areas (🔒) only open with bond. Asking does not cost affinity: ask without fear.", "Son 12 áreas de la vida de la persona, 3 preguntas por consulta. Cada una gasta tiempo, y las áreas delicadas (🔒) solo abren con vínculo. Preguntar no gasta afinidad: pregunta sin miedo.") },
    escuta: { t: L("As palavras acesas", "The lit-up words", "Las palabras encendidas"), x: L("Repare nas palavras marcadas na fala: cada uma é uma porta para uma área que você ainda não investigou. Tocar nela pergunta sobre o que a pessoa acabou de dizer — que é o jeito que funciona de verdade.", "Notice the marked words in the speech: each is a door into an area you have not investigated yet. Tapping one asks about what the person just said — which is the way that actually works.", "Fíjate en las palabras marcadas: cada una es una puerta a un área que aún no investigaste. Tocarla pregunta sobre lo que la persona acaba de decir, que es como funciona de verdad.") },
    corpo: { t: L("O corpo fala antes", "The body speaks first", "El cuerpo habla antes"), x: L("Quando a fala vem com um gesto entre parênteses, você pode nomear o que está vendo — sem acusar. A pessoa se sente vista e afrouxa. Custa tempo de sessão, então compete com uma pergunta — e cabem duas por consulta, o que obriga a escolher QUAL gesto vale nomear.", "When a line comes with a gesture in brackets, you can name what you see — without accusing. The person feels seen and loosens up. It costs session time, so it competes with a question — and two fit per session, which forces you to choose WHICH gesture is worth naming.", "Cuando la frase viene con un gesto entre paréntesis, puedes nombrar lo que ves, sin acusar. La persona se siente vista y se afloja. Cuesta tiempo de sesión, así que compite con una pregunta, y caben dos por consulta, lo que obliga a elegir QUÉ gesto vale nombrar.") },
    silencio: { t: L("O silêncio é intervenção", "Silence is an intervention", "El silencio es intervención"), x: L("Depois de um assunto difícil, a pessoa para. Não preencher o vazio é uma jogada: com vínculo firme, o que vem depois não estava na pergunta. Sem vínculo, o silêncio vira cobrança.", "After a hard subject, the person stops. Not filling the gap is a move: with a firm bond, what comes next was not in the question. Without the bond, silence feels like pressure.", "Tras un tema difícil, la persona se detiene. No llenar el vacío es una jugada: con vínculo firme, lo que viene después no estaba en la pregunta. Sin vínculo, el silencio se siente como exigencia.") },
    confronto: { t: L("Apresentar um achado", "Present a finding", "Presentar un hallazgo"), x: L("A família chega com uma explicação pronta. Quando a prova que a contradiz já está na sua ficha, dá para apresentá-la — e o jogo pergunta DUAS coisas: qual achado você põe na mesa e qual critério do Manual ele preenche. Apresentar uma prova não é mostrar um fato solto: é dizer por que aquele fato desmente a explicação. Achado errado custa 10 de vínculo; critério errado faz a prova cair sem a família entender o que caiu. E exige vínculo: cedo demais não é confronto, é acusação.", "The family arrives with a ready-made explanation. When the evidence that contradicts it is already in your chart, you can present it — and the game asks TWO things: which finding you put on the table and which Manual criterion it fulfils. Presenting evidence is not showing a loose fact: it is saying why that fact disproves the explanation. The wrong finding costs 10 bond; the wrong criterion makes the evidence land without the family understanding what landed. And it needs bond: too early is not confrontation, it is accusation.", "La familia llega con una explicación hecha. Cuando la prueba que la contradice ya está en tu ficha, puedes presentarla, y el juego pregunta DOS cosas: qué hallazgo pones sobre la mesa y qué criterio del Manual cumple. El hallazgo equivocado cuesta 10 de vínculo; el criterio equivocado hace que la prueba caiga sin que la familia entienda qué cayó.") },
    contra: { t: L("O que é seu", "What is yours", "Lo que es tuyo"), x: L("Com o seu estresse alto, aparece no lugar da intuição um pensamento que parece leitura clínica e é a sua reação. O jogo não avisa qual é qual. Ir com ele é rápido e custa vínculo; nomear o que é seu devolve o seu lugar.", "With your stress high, a thought appears in place of intuition that looks like clinical reading and is your own reaction. The game does not tell you which is which. Going with it is quick and costs bond; naming what is yours gives your place back.", "Con tu estrés alto, aparece en lugar de la intuición un pensamiento que parece lectura clínica y es tu reacción. El juego no avisa cuál es cuál. Ir con él es rápido y cuesta vínculo; nombrar lo que es tuyo devuelve tu lugar.") },
    pico: { t: L("O instante", "The moment", "El instante"), x: L("A pessoa chegou no limite, e a palavra que carrega esse instante está acesa. Responder é escolher DE QUE LUGAR você fala — e cada lugar é um eixo da Roda que você treinou. Do lugar certo, ela chega onde não chegava sozinha. A música fica em suspenso enquanto o instante está aberto.", "The person has reached their limit, and the word that carries the moment is lit. Answering means choosing WHERE you speak from — and each place is a Wheel axis you have trained. From the right place, they reach what they could not reach alone. The music holds its breath while the moment is open.", "La persona llegó al límite, y la palabra que carga ese instante está encendida. Responder es elegir DESDE QUÉ LUGAR hablas, y cada lugar es un eje de la Rueda que entrenaste. Desde el lugar correcto, llega adonde no llegaba sola. La música queda en suspenso mientras el instante está abierto.") },
    supervisao: { t: L("Levar o caso", "Taking the case", "Llevar el caso"), x: L("Na faculdade tem uma sala de supervisão. Uma vez por semana, uma colega mais experiente alivia o seu estresse, diz qual pergunta você ainda não fez naquele caso e nomeia a reação que escapou de você na consulta.", "There is a supervision room at the university. Once a week, a more experienced colleague eases your stress, tells you which question you have not asked in that case, and names the reaction that escaped you in session.", "En la facultad hay una sala de supervisión. Una vez por semana, una colega con más experiencia alivia tu estrés, te dice qué pregunta no hiciste en ese caso y nombra la reacción que se te escapó en la consulta."), sug: { when: () => typeof Events !== "undefined" && Events.stress() >= 40, do: L("Leve um caso à supervisão, na faculdade.", "Take a case to supervision, at the university.", "Lleva un caso a supervisión, en la facultad.") } },
    testes: { t: L("Baterias de testes", "Test batteries", "Baterías de pruebas"), x: L("Cada bateria gasta tempo e energia e vem com margem de erro: quanto mais Psicometria, menor o erro. Resultado inconclusivo pode ser repetido por menos tempo.", "Each battery costs time and energy and comes with an error margin: the higher Psychometrics, the smaller the error. An inconclusive result can be repeated for less time.", "Cada batería gasta tiempo y energía y trae margen de error: a más Psicometría, menor el error. Un resultado no concluyente se puede repetir en menos tiempo.") },
    oficina: { t: L("Oficina Clínica", "Clinical Workshop", "Taller Clínico"), x: L("No CAPsi há cinco exercícios do OFÍCIO, separados da Ludoteca da Mente. A Ludoteca treina funções da mente: atenção, memória, inibição. A Oficina treina o que um psicólogo faz — escuta reflexiva (devolver o sentimento, não o conteúdo nem um conselho), triagem de risco (contra critério, não contra susto), genograma, devolutiva em linguagem simples e ética em cinco minutos. Cada um alimenta um eixo diferente da Roda, e a explicação vem DEPOIS da resposta: errar e ler por que é o que ensina.", "At the CAPsi there are five exercises of the CRAFT, separate from the Mind Playroom. The Playroom trains mind functions: attention, memory, inhibition. The Workshop trains what a psychologist does — reflective listening (give back the feeling, not the content or advice), risk triage (against criteria, not against alarm), genogram, plain-language feedback and ethics in five minutes. Each feeds a different Wheel axis, and the explanation comes AFTER the answer: getting it wrong and reading why is what teaches.", "En el CAPsi hay cinco ejercicios del OFICIO, separados de la Ludoteca. La Ludoteca entrena funciones de la mente; el Taller entrena lo que hace un psicólogo: escucha reflexiva, triaje de riesgo, genograma, devolutiva en lenguaje simple y ética. Cada uno alimenta un eje distinto de la Rueda.") },
    arcos: { t: L("Voltar é o que muda", "Coming back is what changes things", "Volver es lo que cambia"), x: L("Cada morador tem três encontros, e eles só andam se você VOLTAR. No primeiro você ouve a fachada — o que a pessoa conta para qualquer um. No segundo, se você voltou noutro dia, ela conta o que está por baixo, e termina com um pedido pequeno e concreto. Cumprir o pedido fecha o arco, rende moedas e experiência, e muda a fala dela com você para sempre. Conversar dez vezes no mesmo dia não adianta: é voltar que conta.", "Every resident has three encounters, and they only move forward if you COME BACK. In the first you hear the front — what the person tells anyone. In the second, if you came back on another day, they tell you what is underneath, and end with a small, concrete request. Fulfilling it closes the arc, pays coins and experience, and changes how they speak to you for good. Talking ten times on the same day does nothing: coming back is what counts.", "Cada vecino tiene tres encuentros, y solo avanzan si VUELVES. En el primero oyes la fachada. En el segundo, si volviste otro día, te cuenta lo que hay debajo y termina con un pedido pequeño y concreto. Cumplirlo cierra el arco y cambia cómo te habla para siempre.") },
    caminhos: { t: L("O que a Roda abre", "What the Wheel opens", "Lo que la Rueda abre"), x: L("Os eixos da Roda davam bônus invisíveis: menos energia, mais precisão, uma dica. A partir do nível 3, três deles põem uma JOGADA NOVA na mesa de investigação. 👁️ Observação: ficar em silêncio e olhar — não custa pergunta, custa 4 min, e numa área de que a pessoa vem desviando, olhar conta como tentativa. 🧩 Raciocínio: perguntar pelo que NÃO acontece — descartar também é diagnosticar, e é mais fácil dizer que algo não acontece. 🤝 Anamnese: perguntar pela pessoa antes do problema — gente fala do passado com muito mais facilidade do que do agora.", "The Wheel's axes used to give invisible bonuses: less energy, more accuracy, a hint. From level 3, three of them put a NEW MOVE on the investigation table. 👁️ Observation: stay silent and watch — costs no question, costs 4 min, and in an area the person keeps steering away from, watching counts as an attempt. 🧩 Reasoning: ask about what does NOT happen — ruling out is diagnosing too, and it is easier to say something does not happen. 🤝 History: ask about the person before the problem — people speak of the past far more easily than of the present.", "Los ejes de la Rueda daban bonus invisibles. Desde el nivel 3, tres de ellos ponen una JUGADA NUEVA sobre la mesa. 👁️ Observación: quedarse en silencio y mirar. 🧩 Razonamiento: preguntar por lo que NO pasa. 🤝 Anamnesis: preguntar por la persona antes del problema.") },
    frio: { t: L("O caso que volta", "The case that comes back", "El caso que vuelve"), x: L("Um diagnóstico errado não fica no passado: algumas semanas depois de você fechar, a pessoa escreve dizendo que piorou e pergunta se você a atenderia de novo. Aceitar reabre o caso por uma semana, com duas consultas — e a sua ficha de antes continua lá, com a hipótese que VOCÊ fechou já marcada e nenhuma ligação travada. Reler o próprio caso com a própria conclusão escrita na frente é a parte difícil da clínica. Recusar custa reputação: a pessoa piorou.", "A wrong diagnosis does not stay in the past: some weeks after you close, the person writes saying they got worse and asks whether you would see them again. Accepting reopens the case for one week, with two sessions — and your old chart is still there, with the hypothesis YOU closed already marked and nothing locked. Rereading your own case with your own conclusion written in front of you is the hard part of clinical work. Declining costs reputation: the person got worse.", "Un diagnóstico equivocado no se queda en el pasado: semanas después de cerrar, la persona escribe diciendo que empeoró y pregunta si la atenderías de nuevo. Aceptar reabre el caso una semana, con dos consultas, y tu ficha de antes sigue ahí con la hipótesis que TÚ cerraste ya marcada.") },
    reformular: { t: L("Perguntar de outro jeito", "Ask it another way", "Preguntar de otra forma"), x: L("Quando a pessoa desvia, insistir na mesma pergunta é o que menos funciona — é a única coisa que um clínico de verdade não faria. Reformule: perguntar PELA BORDA (o que estava em volta, e não o assunto) é o caminho seguro e gasta uma pergunta a mais; NOMEAR a dificuldade de falar disso abre muito quando funciona e custa vínculo quando não; e COMBINAR de voltar noutro dia não rende nada hoje, mas na próxima consulta aquela porta já está destrancada, de graça.", "When the person steers away, pressing the same question is what works least — it is the one thing a real clinician would not do. Rephrase: asking AROUND THE EDGE (what was nearby, not the subject) is the safe route and costs one extra question; NAMING how hard it is to talk about opens a lot when it works and costs bond when it does not; and AGREEING to come back another day yields nothing today, but next session that door is already unlocked, for free.", "Cuando la persona esquiva, insistir en la misma pregunta es lo que menos funciona. Reformula: preguntar POR EL BORDE es el camino seguro y gasta una pregunta más; NOMBRAR lo difícil que es hablar de eso abre mucho cuando funciona y cuesta vínculo cuando no; y ACORDAR volver otro día no rinde hoy, pero en la próxima consulta esa puerta ya está abierta.") },
    lembranca: { t: L("O que ficou da primeira vez", "What stayed from the first time", "Lo que quedó de la primera vez"), x: L("A partir do terceiro encontro, a pessoa devolve com todas as letras a melhor coisa que você disse no primeiro dia. O que fica na memória de quem é atendido não é a técnica: é a frase. Só a melhor, e só uma vez — quem lembra de tudo é ficha, não é gente. Vale a pena escolher bem lá no começo: aquilo volta.", "From the third session on, the person gives back word for word the best thing you said on the first day. What stays in a patient's memory is not the technique: it is the sentence. Only the best one, and only once — what remembers everything is a chart, not a person. It is worth choosing well at the start: it comes back.", "Desde el tercer encuentro, la persona devuelve con todas las letras lo mejor que dijiste el primer día. Lo que queda en la memoria no es la técnica: es la frase. Solo la mejor, y solo una vez.") },
    transito: { t: L("A rua tem carro", "The street has cars", "La calle tiene coches"), x: L("Os carros da Rua Central andam de verdade, nas duas mãos. A pé ou de bicicleta, ser pego na pista tira saúde e joga você para a calçada. Repare nos pedestres: eles saem da frente quando o carro vem, e o carro buzina se alguém demora. A faixa de pedestre está desenhada ali desde sempre — agora ela serve para alguma coisa. Dirigindo, o carro é você: aí não tem atropelamento.", "The cars on Central Street really drive, in both directions. On foot or by bike, being caught in the road costs health and throws you onto the pavement. Watch the pedestrians: they step aside when a car comes, and the car honks if someone is slow. The zebra crossing has been drawn there all along — now it is for something. When you are driving, the car is you: no one runs you over.", "Los coches de la Calle Central circulan de verdad, en los dos sentidos. A pie o en bici, que te pillen en la calzada cuesta salud y te empuja a la acera. Fíjate en los peatones: se apartan cuando viene un coche. El paso de peatones lleva dibujado ahí desde siempre; ahora sirve para algo.") },
    diva: { t: L("O divã", "The couch", "El diván"), x: L("O divã não é um sofá mais caro: é o móvel em que a pessoa deixa de ver o seu rosto. A partir do segundo encontro, com vínculo, você pode oferecê-lo a quem vem sozinho e é adulto. Deitada, ela alcança o assunto que não alcançava olhando para você — a porta das áreas delicadas cede. Em troca, você perde a cara dela: o não verbal simplesmente não existe naquela sessão, e o 👁️ da Roda não tem o que mostrar. Sem vínculo, ela olha para o divã e continua onde está.", "The couch is not a pricier sofa: it is the piece of furniture where the person stops seeing your face. From the second session on, with enough bond, you can offer it to an adult who comes alone. Lying down, they reach the subject they could not reach while looking at you — the door to sensitive areas gives way. In exchange you lose their face: the non-verbal simply does not exist in that session, and the Wheel's 👁️ has nothing to show. Without the bond, they look at the couch and stay where they are.", "El diván no es un sofá más caro: es el mueble donde la persona deja de ver tu rostro. Desde el segundo encuentro, con vínculo, puedes ofrecerlo a quien viene solo y es adulto. Acostada, alcanza el tema que no alcanzaba mirándote: la puerta de las áreas delicadas cede. A cambio, pierdes su cara: lo no verbal no existe en esa sesión.") },
    movelbase: { t: L("A sala é sua", "The room is yours", "La sala es tuya"), x: L("As poltronas e a mesinha também se arrastam na planta, não só o que você comprou. E mover a poltrona move mesmo quem senta nela. A planta avisa o que o arranjo faz com a sessão: longe demais vira conversa gritada, coladas tiram do paciente o espaço de se mexer, e uma poltrona de costas não é consulta nenhuma. Cada poltrona (e o divã) também escolhe o acabamento ali mesmo.", "The armchairs and the coffee table drag around the plan too, not just what you bought. And moving the armchair really moves whoever sits in it. The plan warns what the arrangement does to the session: too far apart becomes a shouted conversation, touching leaves the patient no room to shift, and an armchair with its back turned is no session at all. Each armchair (and the couch) picks its finish right there too.", "Los sillones y la mesita también se arrastran en el plano, no solo lo que compraste. Y mover el sillón mueve de verdad a quien se sienta en él. El plano avisa lo que el arreglo hace con la sesión.") },
    escolhadela: { t: L("A escolha dela já é o teste", "Her choice is already the test", "Su elección ya es la prueba"), x: L("Antes do primeiro item, você oferece duas portas e deixa a pessoa escolher por qual entra — e a escolha diz o que nenhuma pontuação diz. Quem já sabe onde falha desvia da porta difícil ANTES de tentar; quem é impulsivo pega a mais difícil sem medir; quem está tenso negocia o começo para não errar de saída. E quando ela tropeça no meio da tarefa, ela olha para você: ficar calado mantém a medida limpa, dizer que está indo bem acalma e marca a pontuação com ressalva, e perguntar o que passou pela cabeça dela rende a melhor frase do teste inteiro — e custa um minuto.", "Before the first item, you offer two doors and let the person choose which one to go through — and the choice says what no score says. Someone who already knows where they fail steers away from the hard door BEFORE trying; someone impulsive takes the hardest without measuring; someone tense negotiates the start so as not to fail at the outset. And when they stumble mid-task, they look at you: staying silent keeps the measure clean, saying they are doing fine calms them and flags the score with a caveat, and asking what went through their head yields the best sentence in the whole test — and costs a minute.", "Antes del primer ítem, ofreces dos puertas y dejas que la persona elija por cuál entra, y la elección dice lo que ninguna puntuación dice. Quien ya sabe dónde falla esquiva la puerta difícil ANTES de intentarlo; quien es impulsivo toma la más difícil sin medir; quien está tenso negocia el comienzo. Y cuando tropieza, te mira: callar mantiene la medida limpia, decir que va bien calma y marca la puntuación con salvedad, y preguntar qué le pasó por la cabeza rinde la mejor frase de toda la prueba.") },
    projetivas: { t: L("Técnicas projetivas", "Projective techniques", "Técnicas proyectivas"), x: L("Escolha a técnica e a área delicada que quer alcançar. A técnica certa revela o achado com menos desgaste de vínculo; uma leitura precipitada deixa uma pista enganosa.", "Pick the technique and the sensitive area you want to reach. The right technique reveals the finding with less bond loss; a hasty reading leaves a misleading clue.", "Elige la técnica y el área delicada que quieres alcanzar. La técnica adecuada revela el hallazgo con menos desgaste de vínculo; una lectura precipitada deja una pista engañosa.") },
    evidencia: { t: L("Quem liga os pontos é você", "You are the one connecting the dots", "Quien une los puntos eres tú"), x: L("Na aba Hipóteses, abra uma hipótese e diga, achado por achado, o que pesa A FAVOR e o que pesa CONTRA. As barras verde e vermelha são a SUA marcação — o jogo não faz essa conta por você. Ao fechar o caso ele confere o que você ligou: as ligações que se sustentam contam a favor da sua nota, e as que não se sustentam custam. Fechar sem marcar nada é fechar no escuro.", "In the Hypotheses tab, open a hypothesis and say, finding by finding, what counts FOR and what counts AGAINST. The green and red bars are YOUR marking — the game does not do that maths for you. When you close the case it checks what you linked: links that hold up count towards your grade, and the ones that do not cost you. Closing without marking anything is closing blind.", "En la pestaña Hipótesis, abre una hipótesis y di, hallazgo por hallazgo, qué pesa A FAVOR y qué EN CONTRA. Las barras verde y roja son TU marcación: el juego no hace esa cuenta por ti. Al cerrar el caso comprueba lo que uniste: las conexiones que se sostienen cuentan a favor de tu nota, y las que no, cuestan. Cerrar sin marcar nada es cerrar a ciegas.") },
    estacoes: { t: L("As estações do ano", "The seasons", "Las estaciones del año"), x: L("O ano do jogo tem 12 semanas: três por estação, começando no verão. A cidade muda de cor junto, e a festa cai sempre na ÚLTIMA semana da estação — Páscoa no fim do outono, Halloween no fim do inverno, Natal no fim da primavera. As figuras de feriado só andam pela cidade na época delas: um Papai Noel em março não queria dizer nada, e agora ele só aparece no Natal. Quem perdeu a época espera o ano virar.", "The game's year has 12 weeks: three per season, starting in summer. The city changes colour along with it, and the holiday always falls in the LAST week of the season — Easter at the end of autumn, Halloween at the end of winter, Christmas at the end of spring. Holiday figures only walk the city in their own season: a Father Christmas in March meant nothing, and now he only shows up at Christmas. Miss the season and you wait for the year to turn.", "El año del juego tiene 12 semanas: tres por estación, empezando en verano. La ciudad cambia de color, y la fiesta cae siempre en la ÚLTIMA semana de la estación. Las figuras de feriado solo andan por la ciudad en su época: un Papá Noel en marzo no quería decir nada.") },
    desvio: { t: L("O que a pessoa não diz", "What the person does not say", "Lo que la persona no dice"), x: L("Quando falta confiança, a pessoa desvia do assunto — e isso não é um \"não deu\". Perguntar três vezes sobre a mesma área e ouvir desvio nas três vira uma observação na ficha: não sobre o conteúdo, mas sobre o quanto aquele assunto custa para ela. Às vezes a área mais evitada é a que mais diz.", "When trust is missing, the person steers away from the subject — and that is not a \"no luck\". Asking three times about the same area and being deflected all three times becomes an observation in the chart: not about the content, but about how much that subject costs them. Sometimes the most avoided area is the one that says the most.", "Cuando falta confianza, la persona esquiva el tema, y eso no es un \"no salió\". Preguntar tres veces sobre la misma área y ser esquivado las tres se convierte en una observación en la ficha: no sobre el contenido, sino sobre cuánto le cuesta ese tema.") },
    turva: { t: L("O seu cansaço entra na escuta", "Your exhaustion gets into your listening", "Tu cansancio entra en la escucha"), x: L("Com o estresse alto, um trecho da fala chega embaçado. O paciente não falou diferente — VOCÊ é que não está escutando inteiro. Tocar no trecho recompõe, mas o recado é outro: atender exausto custa. Durma, faça uma aula na academia ou leve o caso à supervisão.", "With high stress, a stretch of the speech arrives blurred. The patient did not speak differently — YOU are the one not listening whole. Tapping the stretch refocuses it, but the point is elsewhere: seeing patients exhausted has a cost. Sleep, take a class at the gym, or bring the case to supervision.", "Con el estrés alto, un tramo de la frase llega borroso. El paciente no habló distinto: TÚ no estás escuchando entero. Tocar el tramo lo recompone, pero el recado es otro: atender agotada cuesta.") },
    pedidos: { t: L("Pedir a quem vê o que você não vê", "Asking those who see what you cannot", "Pedir a quien ve lo que tú no ves"), x: L("Dentro da sala você só alcança o que a pessoa conta. A escola vê a rotina, o médico vê o corpo, a família viu o começo, e quem atendeu antes tem o registro. Na aba 📎 Pedidos do celular você pede a fonte que quiser: custa moedas e DIAS de espera — não tempo de sessão. Quando chega, o achado entra na ficha sozinho. Vale pedir cedo, porque o material demora.", "Inside the room you only reach what the person tells you. The school sees the routine, the doctor sees the body, the family saw the beginning, and whoever treated them before has the records. In the phone's 📎 Requests tab you ask whichever source you want: it costs coins and DAYS of waiting — not session time. When it arrives, the finding goes into the chart by itself. Worth asking early, because the material takes time.", "Dentro de la sala solo alcanzas lo que la persona cuenta. La escuela ve la rutina, el médico ve el cuerpo, la familia vio el comienzo, y quien atendió antes tiene el registro. En la pestaña 📎 Pedidos del celular pides la fuente que quieras: cuesta monedas y DÍAS de espera, no tiempo de consulta. Cuando llega, el hallazgo entra solo en la ficha.") },
    tempo: { t: L("A ordem das coisas", "The order of things", "El orden de las cosas"), x: L("Muita decisão clínica se joga na ORDEM: o sintoma veio antes ou depois da perda? o medo começou junto com o afastamento, ou o afastamento veio do medo? Na aba Linha do tempo você põe cada achado no seu tempo — antes de começar, quando começou, desde então, agora. O jogo não corrige o seu julgamento: ele só avisa quando você contraria o que a pessoa disse com todas as letras.", "A lot of clinical decisions hinge on ORDER: did the symptom come before or after the loss? did the fear start along with the withdrawal, or did the withdrawal come from the fear? In the Timeline tab you place each finding in its time — before it started, when it started, since then, now. The game does not correct your judgement: it only warns when you contradict what the person said in so many words.", "Muchas decisiones clínicas se juegan en el ORDEN: ¿el síntoma vino antes o después de la pérdida? ¿el miedo empezó junto con el aislamiento, o el aislamiento vino del miedo? En la pestaña Línea del tiempo colocas cada hallazgo en su tiempo. El juego no corrige tu juicio: solo avisa cuando contradices lo que la persona dijo con todas las letras.") },
    bug: { t: L("Achou um problema?", "Found a problem?", "¿Encontraste un problema?"), x: L("Em Opções há 🐞 Reportar um problema. Você conta o que viu; o jogo junta sozinho a versão, a tela, o aparelho, os últimos botões que você tocou e o erro que apareceu por baixo. Se algo quebrar de verdade, o botão aparece sozinho no canto da tela.", "In Options there is 🐞 Report a problem. You tell what you saw; the game gathers the version, the screen, your device, the last buttons you tapped and the underlying error. If something really breaks, the button shows up by itself in the corner of the screen.", "En Opciones hay 🐞 Reportar un problema. Tú cuentas lo que viste; el juego reúne la versión, la pantalla, el aparato, los últimos botones que tocaste y el error de fondo. Si algo se rompe de verdad, el botón aparece solo en la esquina.") },
    caderno: { t: L("Caderno de campo", "Field notebook", "Cuaderno de campo"), x: L("O caderno tem janela própria, no botão 🗒️ ao lado da ficha. As \"Observações desta consulta\" são do jogo: ele anota o que você fez. O caderno é o seu rascunho — uma suspeita, uma palavra que a pessoa repetiu, algo a perguntar na próxima. Depois você PRENDE a anotação num achado ou numa hipótese, e ela passa a aparecer junto daquilo. É o que transforma texto solto em raciocínio organizado.", "The notebook has its own window, on the 🗒️ button beside the chart. The \"Notes from this session\" belong to the game: it records what you did. The notebook is your scratch pad — a hunch, a word the person repeated, something to ask next time. Then you PIN the note to a finding or a hypothesis, and it shows up alongside it. That is what turns loose text into organised reasoning.", "El cuaderno tiene ventana propia, en el botón 🗒️ junto a la ficha. Las \"Observaciones de esta consulta\" son del juego: registra lo que hiciste. El cuaderno es tu borrador: una sospecha, una palabra que la persona repitió, algo que preguntar la próxima vez. Luego PRENDES la nota a un hallazgo o a una hipótesis y aparece junto a eso.") },
    criterio: { t: L("O Manual vira prova", "The Manual becomes evidence", "El Manual se vuelve prueba"), x: L("Marcar \"a favor\" sem dizer de quê é opinião. Ao apontar um achado a favor de uma hipótese, escolha QUAL critério do Manual ele preenche. A ficha então mostra quais critérios daquele transtorno ainda estão sem prova nenhuma — e é isso que separa \"eu acho que é TDAH\" de \"é TDAH, e aqui estão os cinco critérios sustentados\". Dois achados no mesmo critério não valem por dois.", "Marking \"for\" without saying what for is an opinion. When you mark a finding in favour of a hypothesis, choose WHICH criterion of the Manual it fulfils. The chart then shows which criteria of that disorder still have no evidence at all — and that is what separates \"I think it's ADHD\" from \"it's ADHD, and here are the five criteria supported\". Two findings on the same criterion do not count twice.", "Marcar \"a favor\" sin decir de qué es opinión. Al señalar un hallazgo a favor de una hipótesis, elige QUÉ criterio del Manual cumple. La ficha muestra entonces qué criterios de ese trastorno siguen sin prueba alguna, y eso separa \"creo que es TDAH\" de \"es TDAH, y aquí están los cinco criterios sustentados\". Dos hallazgos en el mismo criterio no valen por dos.") },
    trio: { t: L("Conferir em bloco", "Checking in blocks", "Comprobar en bloque"), x: L("Conferir uma ligação por vez viraria tentativa e erro: marca, vê se acendeu, corrige. Por isso você aponta TRÊS de uma vez, e o jogo responde só quantas não se sustentam — nunca quais. Se as três estiverem de pé, elas travam (🔒) e viram raciocínio firmado, que ninguém mais mexe. Se não, você volta a pensar nas três.", "Checking one link at a time would be trial and error: mark it, see if it lights up, fix it. So you submit THREE at once, and the game only answers how many do not hold up — never which. If all three stand, they lock (🔒) as settled reasoning that nobody touches again. If not, you go back and rethink all three.", "Comprobar una conexión a la vez sería ensayo y error: marcas, ves si se enciende, corriges. Por eso presentas TRES a la vez, y el juego solo responde cuántas no se sostienen, nunca cuáles. Si las tres se sostienen, quedan fijadas (🔒). Si no, vuelves a pensar las tres.") },
    contradicao: { t: L("Duas coisas que não cabem juntas", "Two things that do not fit together", "Dos cosas que no caben juntas"), x: L("Se você apontou o mesmo achado a favor de duas hipóteses diferentes, a ficha avisa: as duas não podem estar certas ao mesmo tempo. Ou uma das marcações cai, ou você assume a comorbidade no diferencial — e aí passam a caber.", "If you marked the same finding in favour of two different hypotheses, the chart says so: both cannot be right at once. Either one of the marks goes, or you declare the comorbidity in the differential — and then they do fit.", "Si marcaste el mismo hallazgo a favor de dos hipótesis distintas, la ficha avisa: ambas no pueden ser correctas a la vez. O cae una de las marcas, o asumes la comorbilidad en el diferencial, y entonces sí caben.") },
    diferencial: { t: L("Diagnóstico diferencial", "Differential diagnosis", "Diagnóstico diferencial"), x: L("Para fechar o caso é preciso descartar as hipóteses concorrentes com uma evidência que as contradiga. Marque a hipótese principal e, se fizer sentido, uma comorbidade.", "To close the case you must rule out competing hypotheses with contradicting evidence. Mark the main hypothesis and, if it makes sense, a comorbidity.", "Para cerrar el caso hay que descartar las hipótesis competidoras con una evidencia que las contradiga. Marca la hipótesis principal y, si tiene sentido, una comorbilidad.") },
    laudo: { t: L("Laudo", "Report", "Informe"), x: L("Monte o laudo com resultados, conclusão, recomendações, limitações e a linguagem certa para quem vai ler. A qualidade define o pagamento e a Reputação Acadêmica.", "Build the report with results, conclusion, recommendations, limitations and the right language for the reader. Quality sets the payment and Academic Reputation.", "Monta el informe con resultados, conclusión, recomendaciones, limitaciones y el lenguaje adecuado para quien lo lee. La calidad define el pago y la Reputación Académica.") },
    devolutiva: { t: L("Devolutiva", "Feedback session", "Devolutiva"), x: L("Conduza a devolutiva em rodadas: respostas empáticas e claras aumentam a adesão ao tratamento e a Reputação da Clínica; tom alarmista ou técnico demais derruba.", "Lead the feedback in rounds: empathetic, clear answers raise treatment adherence and Clinic Reputation; an alarmist or too technical tone lowers them.", "Conduce la devolutiva en rondas: respuestas empáticas y claras aumentan la adhesión al tratamiento y la Reputación de la Clínica; un tono alarmista o demasiado técnico las baja.") },
    roda: { modal: "wheel-modal", t: L("Roda do Psicólogo", "Psychologist Wheel", "Rueda del Psicólogo"), x: L("Os 8 eixos crescem com o que você faz. Com 3 pontos o bônus do eixo liga. O perfil dominante aparece depois de algumas escolhas.", "The 8 axes grow with what you do. At 3 points the axis bonus switches on. The dominant profile shows up after a few choices.", "Los 8 ejes crecen con lo que haces. Con 3 puntos se activa el bono del eje. El perfil dominante aparece tras algunas elecciones."), sug: { when: () => true, do: L("Abra a Roda e veja qual eixo está mais perto de ligar.", "Open the Wheel and see which axis is closest to switching on.", "Abre la Rueda y mira qué eje está más cerca de activarse.") } },
    missoes: { modal: "quests-modal", t: L("Missões", "Quests", "Misiones"), x: L("Na cidade traz a sua história aqui, em etapas — uma de cada vez, e a seguinte só aparece quando você fecha a anterior — e uma lista de coisas soltas para fazer. Hoje mostra as tarefas do dia; Figuras traz pistas de pessoas para achar no mapa; Carreira mostra o que cada reputação desbloqueia.", "In town holds your story here, in steps — one at a time, and the next only shows once you close the previous one — plus a list of loose things to do. Today shows the day's tasks; Figures brings clues to people to find on the map; Career shows what each reputation unlocks.", "En la ciudad trae tu historia aquí, por etapas — una a la vez, y la siguiente solo aparece cuando cierras la anterior — y una lista de cosas sueltas por hacer. Hoy muestra las tareas del día; Figuras trae pistas de personas por encontrar en el mapa; Carrera muestra lo que desbloquea cada reputación."), sug: { when: () => typeof Missoes !== "undefined" && Boolean(Missoes.etapaAtual()), do: () => Missoes.etapaAtual().nome } },
    acompanhamento: { t: L("Psicoterapia contínua", "Ongoing therapy", "Psicoterapia continua"), x: L("Quem aceitou terapia ganha sessões de acompanhamento na agenda e uma barra de progresso. Com 100% e 6 sessões você pode dar alta (Celular → Acompanhamento). Faltar tira progresso.", "People who accepted therapy get follow-up sessions in the schedule and a progress bar. At 100% and 6 sessions you can discharge (Phone → Follow-up). Missing sessions lowers progress.", "Quien aceptó terapia tiene sesiones de seguimiento en la agenda y una barra de progreso. Con 100% y 6 sesiones puedes dar el alta (Celular → Seguimiento). Faltar quita progreso."), sug: { when: () => typeof Care !== "undefined" && Care.list().length > 0, do: L("Veja a aba Acompanhamento do celular.", "Check the phone's Follow-up tab.", "Mira la pestaña Seguimiento del celular.") } },
    entrada: { t: L("A pessoa entra pela porta", "The person walks in", "La persona entra por la puerta"), x: L("Desde a 7.8 o paciente (e quem vem com ele) não aparece mais sentado do nada: entra pela porta e caminha até a poltrona, contornando os móveis que você pôs na planta. Se a sala estiver apertada ou o aparelho lento, ele senta assim que chegar perto — ninguém fica plantado no meio da sala. Com movimento reduzido ligado (Opções → Acesso), a caminhada não acontece: a pessoa já começa sentada.", "Since 7.8 the patient (and whoever comes along) no longer appears seated out of nowhere: they come through the door and walk to the armchair, going around the furniture you placed in the plan. If the room is tight or the device is slow, they sit as soon as they get close — nobody is left standing in the middle of the room. With reduced motion on (Options → Access), the walk does not happen: the person starts seated.", "Desde la 7.8 el paciente (y quien lo acompaña) ya no aparece sentado de la nada: entra por la puerta y camina hasta el sillón, rodeando los muebles que pusiste en el plano. Si la sala está apretada o el aparato es lento, se sienta en cuanto llega cerca — nadie se queda plantado en medio de la sala. Con movimiento reducido activado (Opciones → Acceso), la caminata no ocurre: la persona empieza sentada."), sug: { when: () => typeof session !== "undefined" && Boolean(session) && Boolean(settings.graphics3d), do: L("Repare no começo da consulta: a porta, o caminho e a poltrona.", "Watch the start of the session: the door, the path and the armchair.", "Fíjate al principio de la consulta: la puerta, el camino y el sillón.") } },
    cancelou: { t: L("Quem desmarca, e por quê", "Who cancels, and why", "Quién cancela, y por qué"), x: L("A partir da 2ª semana um paciente pode desmarcar a consulta — e não é sorte: desmarca quem tem menos vínculo com você, adesão baixa e uma consulta ruim para trás. Só a 2ª e a 3ª consulta cancelam (a 1ª é a porta de entrada, a 4ª é o diagnóstico), no máximo uma por semana. O eixo 🤝 Anamnese derruba essa chance de verdade, e a recepcionista, que confirma os horários, derruba mais um tanto. O recado chega no celular e o horário fica livre.", "From week 2 on a patient may cancel the session — and it is not luck: whoever cancels has less bond with you, low adherence and a poor session behind them. Only the 2nd and 3rd sessions cancel (the 1st is the way in, the 4th is the diagnosis), at most one per week. The 🤝 History axis genuinely lowers that chance, and the receptionist, who confirms appointments, lowers it further. The message arrives on your phone and the slot is free.", "A partir de la 2ª semana un paciente puede cancelar la consulta — y no es suerte: cancela quien tiene menos vínculo contigo, adhesión baja y una consulta mala atrás. Solo la 2ª y la 3ª cancelan (la 1ª es la puerta de entrada, la 4ª es el diagnóstico), como máximo una por semana. El eje 🤝 Anamnesis baja esa probabilidad de verdad, y la recepcionista, que confirma los horarios, la baja más. El recado llega al celular y el horario queda libre."), sug: { when: () => typeof FU !== "undefined" && FU.cancelados && Object.keys(FU.cancelados()).length > 0, do: L("Veja o recado em Celular → Mensagens.", "Check the message in Phone → Messages.", "Mira el mensaje en Celular → Mensajes.") } },
    apedecidade: { t: L("A cidade se atravessa a pé", "The city can be crossed on foot", "La ciudad se cruza a pie"), x: L("Os marcadores do mapa continuam ali para ir direto, mas agora dá para ANDAR de um lugar ao outro: a praça sai da Rua Central, o parque e o bairro saem da praça, a praia sai da rua do lazer, o farol sai da praia, o observatório sai do campus, e a estação e a feira de domingo também têm caminho. Procure as setas nas bordas de cada lugar — toda passagem tem volta.", "The map markers are still there for going straight to a place, but now you can WALK from one to another: the square leaves from Central Street, the park and the neighbourhood from the square, the beach from Leisure Street, the lighthouse from the beach, the observatory from the campus, and the station and the Sunday fair have paths too. Look for the arrows at the edges of each place — every passage has a way back.", "Los marcadores del mapa siguen ahí para ir directo, pero ahora puedes CAMINAR de un lugar a otro: la plaza sale de la Calle Central, el parque y el barrio de la plaza, la playa de la calle del ocio, el faro de la playa, el observatorio del campus, y la estación y la feria del domingo también tienen camino. Busca las flechas en los bordes de cada lugar — toda pasarela tiene vuelta."), sug: { when: () => typeof City !== "undefined" && City.loc && City.loc(), do: L("Procure a seta na borda do lugar onde você está.", "Look for the arrow at the edge of where you are.", "Busca la flecha en el borde del lugar donde estás.") } },
    regioes: { t: L("As regiões do mundo na lapela", "The world's regions on your lapel", "Las regiones del mundo en la solapa"), x: L("Na loja de souvenires, 196 países têm estado, província ou região — são 5.326 peças, pela lista oficial ISO 3166-2. Quem tem bandeira própria mostra a sua; o resto ganha um selo com as cores do país. Escreva duas letras na busca e ela procura DENTRO dos países: dá para achar a Baviera sem abrir a Alemanha. Lista longa vem de 60 em 60 — o Reino Unido tem 221.", "In the souvenir shop, 196 countries have states, provinces or regions — 5,326 pieces, from the official ISO 3166-2 list. Those with their own flag show it; the rest get a seal in the country's colours. Type two letters in the search box and it looks INSIDE the countries: you can find Bavaria without opening Germany. Long lists come 60 at a time — the UK has 221.", "En la tienda de souvenirs, 196 países tienen estado, provincia o región — son 5.326 piezas, según la lista oficial ISO 3166-2. Quien tiene bandera propia la muestra; el resto recibe un sello con los colores del país. Escribe dos letras en la búsqueda y también busca DENTRO de los países: puedes encontrar Baviera sin abrir Alemania. La lista larga viene de 60 en 60 — el Reino Unido tiene 221."), sug: { when: () => typeof Pins !== "undefined" && Pins.subs && Pins.subs().length > 100, do: L("Loja → Souvenirs e acessórios → Bandeiras do mundo.", "Shop → Souvenirs and accessories → Flags of the world.", "Tienda → Souvenirs y accesorios → Banderas del mundo.") } },
    ambiguo: { t: L("O achado que não decide nada", "The finding that decides nothing", "El hallazgo que no decide nada"), x: L("Alguns sintomas pesam IGUAL para dois quadros — insônia serve à depressão e à ansiedade, conferir o pulso serve ao pânico e ao sintoma somático. A ficha marca esses achados com 🔀. Eles contam como material clínico, mas não descartam ninguém: o laudo recusa quem tenta derrubar uma hipótese com um achado que também a sustenta, e conferir em bloco não firma uma marcação dessas. É a regra do diferencial: evidência que serve aos dois lados não é evidência.", "Some symptoms weigh THE SAME for two conditions — insomnia serves depression and anxiety, pulse-checking serves panic and somatic symptom disorder. The chart marks those findings with 🔀. They count as clinical material, but they rule nothing out: the report refuses anyone trying to knock down a hypothesis with a finding that also supports it, and block-checking does not firm such a marking. That is the rule of the differential: evidence that serves both sides is not evidence.", "Algunos síntomas pesan IGUAL para dos cuadros — el insomnio sirve a la depresión y a la ansiedad, tomarse el pulso sirve al pánico y al síntoma somático. La ficha marca esos hallazgos con 🔀. Cuentan como material clínico, pero no descartan a nadie: el informe rechaza a quien intenta derribar una hipótesis con un hallazgo que también la sostiene, y comprobar en bloque no fija esa marca. Es la regla del diferencial: evidencia que sirve a ambos lados no es evidencia."), sug: { when: () => typeof Dx !== "undefined" && Dx.cur && Dx.cur() && Dx.foundList(Dx.cur()).some((d) => Dx.ambiguo(Dx.cur(), d.id)), do: L("Procure o 🔀 na aba Achados.", "Look for the 🔀 in the Findings tab.", "Busca el 🔀 en la pestaña Hallazgos.") } },
    comorbidade: { t: L("Às vezes são duas coisas", "Sometimes it is two things", "A veces son dos cosas"), x: L("Nem todo caso se resolve escolhendo uma hipótese. Quando você marca evidência a favor de duas e o caso comporta as duas, dá para assumir COMORBIDADE em vez de escolher — e aí a contradição entre as suas marcações deixa de ser erro e passa a ser leitura. A Trilha avisa quando essa porta se abre.", "Not every case is solved by picking one hypothesis. When you mark evidence in favour of two and the case supports both, you can take COMORBIDITY instead of choosing — and then the contradiction between your markings stops being an error and becomes a reading. The Path tab tells you when that door opens.", "No todo caso se resuelve eligiendo una hipótesis. Cuando marcas evidencia a favor de dos y el caso admite ambas, puedes asumir COMORBILIDAD en vez de elegir — y entonces la contradicción entre tus marcas deja de ser error y pasa a ser lectura. La pestaña Ruta avisa cuando esa puerta se abre."), sug: { when: () => typeof Dx !== "undefined" && typeof PsicoDx !== "undefined" && Dx.cur && Dx.cur() && (Dx.kase(Dx.cur()) || {}).comorbid, do: L("Veja a aba Trilha: o passo 'Duas coisas ao mesmo tempo?'.", "Check the Path tab: the step 'Two things at once?'.", "Mira la pestaña Ruta: el paso '¿Dos cosas a la vez?'.") } },
    descarte: { t: L("Concluir é derrubar as outras", "Concluding means knocking the others down", "Concluir es derribar a las otras"), x: L("O laudo não sai só com a sua conclusão: para cada hipótese concorrente você aponta o achado que a contradiz — e tem de ser um que você marcou CONTRA ela na ficha (aba Hipóteses). Sem evidência marcada, o botão de emitir fica travado e o caminho é voltar à ficha. É assim no consultório também: dizer o que é, sem dizer por que não é o resto, é opinião.", "The report is not issued on your conclusion alone: for each competing hypothesis you point to the finding that contradicts it — and it must be one you marked AGAINST it in the chart (Hypotheses tab). With no marked evidence the issue button stays locked and the way through is back to the chart. It works like that in practice too: saying what it is, without saying why it is not the rest, is an opinion.", "El informe no sale solo con tu conclusión: para cada hipótesis competidora señalas el hallazgo que la contradice — y tiene que ser uno que marcaste EN CONTRA en la ficha (pestaña Hipótesis). Sin evidencia marcada el botón de emitir queda bloqueado y el camino es volver a la ficha. En la clínica es igual: decir qué es, sin decir por qué no es el resto, es opinión."), sug: { when: () => typeof PsicoDx !== "undefined" && typeof session !== "undefined" && Boolean(session) && (session.sess || 1) >= 4, do: L("Marque na ficha uma evidência contra cada hipótese que você vai descartar.", "In the chart, mark one piece of evidence against each hypothesis you will rule out.", "En la ficha, marca una evidencia en contra de cada hipótesis que vas a descartar.") } },
    reputacao: { t: L("Para que serve cada reputação", "What each reputation is for", "Para qué sirve cada reputación"), x: L("🏥 Clínica abre estrutura e gente — sala de espera, recepção, segunda sala, estagiário, psicólogo júnior, clínica de referência — e também QUEM chega até você: os quadros mais difíceis só são encaminhados quando a clínica tem nome (pânico com 10, TDAH com 20, esgotamento no trabalho com 35). 🎓 Acadêmica abre aula, artigo, congresso, orientação, bolsa de pesquisa (renda semanal sem atender) e supervisão avançada (duas por semana, com alívio maior). Veja em Missões → Carreira.", "🏥 Clinic opens structure and people — waiting room, reception, second room, intern, junior psychologist, reference clinic — and also WHO reaches you: harder presentations are only referred once the clinic has a name (panic at 10, ADHD at 20, work exhaustion at 35). 🎓 Academic opens teaching, articles, conferences, supervising interns, a research grant (weekly income without seeing patients) and advanced supervision (twice a week, with greater relief). See Quests → Career.", "🏥 Clínica abre estructura y gente — sala de espera, recepción, segunda sala, practicante, psicólogo júnior, clínica de referencia — y también QUIÉN llega hasta ti: los cuadros más difíciles solo se derivan cuando la clínica tiene nombre (pánico con 10, TDAH con 20, agotamiento laboral con 35). 🎓 Académica abre clases, artículos, congresos, orientación, beca de investigación (ingreso semanal sin atender) y supervisión avanzada (dos por semana, con mayor alivio). Míralo en Misiones → Carrera."), sug: { when: () => typeof Wheel !== "undefined" && (Wheel.rep().clinica >= 4 || Wheel.rep().academica >= 4), do: L("Confira o que já abriu em Missões → Carreira.", "Check what has opened in Quests → Career.", "Mira lo que ya se abrió en Misiones → Carrera.") } },
    habilidades: { t: L("Os dois eixos que agora falam", "The two axes that now speak", "Los dos ejes que ahora hablan"), x: L("📝 Laudo e 🩺 Articulação cresciam sem aparecer na consulta. Agora cada um tem uma ação: Formular síntese costura numa frase os achados que VOCÊ já tem (não revela nada novo — organiza), e Pedir parecer traz a leitura de um colega dizendo ONDE olhar. Uma vez por consulta cada, duas na maestria. E o bônus de todo eixo tem três degraus: 3 liga, 6 amplia, 10 é maestria.", "📝 Report and 🩺 Multidisciplinary used to grow without ever showing up in session. Now each has an action: Draft a synthesis stitches the findings YOU already have into one sentence (it reveals nothing new — it organises), and Ask for an opinion brings a colleague's reading of WHERE to look. Once per session each, twice at mastery. And every axis bonus has three steps: 3 switches on, 6 widens, 10 is mastery.", "📝 Informe y 🩺 Articulación crecían sin aparecer en la consulta. Ahora cada uno tiene una acción: Formular síntesis cose en una frase los hallazgos que YA tienes (no revela nada nuevo — organiza), y Pedir parecer trae la lectura de un colega diciendo DÓNDE mirar. Una vez por consulta cada una, dos en la maestría. Y el bono de cada eje tiene tres escalones: 3 enciende, 6 amplía, 10 es maestría."), sug: { when: () => typeof Wheel !== "undefined" && (Wheel.active("laudo") || Wheel.active("multi")), do: L("Repare nos botões 📝 e 🩺 na consulta.", "Look for the 📝 and 🩺 buttons in session.", "Fíjate en los botones 📝 y 🩺 en la consulta.") } },
    rede: { t: L("A rede é gente, não papel", "The network is people, not paperwork", "La red es gente, no papel"), x: L("Na escola, no CAPS, no hospital e no fórum dá para sentar com quem vê a pessoa em outro lugar. A ordem importa: quem chega com a conclusão pronta ouve menos, quem pergunta primeiro recebe o que a sala não mostra (e isso entra na ficha como achado da rede), e combinar a conduta depois de ouvir sobe a adesão ao tratamento. Uma reunião por caso a cada semana.", "At the school, the CAPS, the hospital and the courthouse you can sit with whoever sees the person elsewhere. Order matters: whoever arrives with the conclusion ready hears less, whoever asks first receives what the room does not show (and it goes into the chart as a network finding), and agreeing on conduct after listening raises treatment adherence. One meeting per case each week.", "En la escuela, el CAPS, el hospital y el juzgado puedes sentarte con quien ve a la persona en otro lugar. El orden importa: quien llega con la conclusión hecha escucha menos, quien pregunta primero recibe lo que la sala no muestra (y entra en la ficha como hallazgo de la red), y acordar la conducta después de escuchar sube la adhesión al tratamiento. Una reunión por caso cada semana."), sug: { when: () => typeof Rede !== "undefined" && typeof Dx !== "undefined" && Boolean(Rede.casoAtual()), do: L("Passe na escola ou no CAPS do caso que você está atendendo.", "Drop by the school or the CAPS of the case you are seeing.", "Pasa por la escuela o el CAPS del caso que estás atendiendo.") } },
    defesas: { t: L("A defesa tem forma", "The defence has a shape", "La defensa tiene forma"), x: L("Quando a pergunta chega antes da confiança, a pessoa não desvia de qualquer jeito: ela se fecha com a forma que aprendeu — cisão, negação, racionalização, projeção, evitação, minimização, retraimento ou desconfiança. Ler essa forma é jogada: acertar não arromba a porta, abre um pouco (a pessoa se sente lida), vale eixo Observação e fica escrito na ficha. Errar não custa nada — punir leitura clínica viraria tentativa e erro. Uma leitura por área a cada consulta.", "When the question arrives before trust does, the person does not deflect just any way: they close up with the shape they learned — splitting, denial, rationalisation, projection, avoidance, minimisation, withdrawal or guardedness. Reading that shape is a move: getting it right does not force the door, it opens it a little (the person feels read), it counts for the Observation axis and it is written in the chart. Getting it wrong costs nothing — punishing clinical reading would turn it into trial and error. One reading per area each session.", "Cuando la pregunta llega antes que la confianza, la persona no se desvía de cualquier forma: se cierra con la forma que aprendió — escisión, negación, racionalización, proyección, evitación, minimización, retraimiento o desconfianza. Leer esa forma es jugada: acertar no fuerza la puerta, la abre un poco (la persona se siente leída), vale eje Observación y queda escrito en la ficha. Errar no cuesta nada — castigar la lectura clínica la volvería ensayo y error. Una lectura por área en cada consulta."), sug: { when: () => typeof Defesa !== "undefined" && typeof session !== "undefined" && Boolean(session), do: L("Quando a pessoa se fechar, leia como ela se fechou.", "When the person closes up, read how they closed up.", "Cuando la persona se cierre, lee cómo se cerró.") } },
    adesao: { t: L("A adesão vem da devolutiva", "Adherence comes from the feedback session", "La adhesión viene de la devolutiva"), x: L("A conta que a devolutiva fechou não morre ali: adesão baixa faz a pessoa chegar resistente (e render menos), faltar sem avisar e, se as faltas somarem, abandonar o tratamento. Tom alarmista e jargão com família leiga é o que mais derruba. Sessão boa reconstrói a adesão, e quem abandonou ainda atende uma ligação — uma vez.", "The number the feedback session closed does not die there: low adherence makes the person arrive resistant (and gain less), miss without warning and, if the misses add up, drop out. An alarming tone and jargon with a lay family are what sink it most. A good session rebuilds adherence, and whoever dropped out still takes one phone call — once.", "La cuenta que cerró la devolutiva no muere ahí: una adhesión baja hace que la persona llegue resistente (y avance menos), falte sin avisar y, si las faltas suman, abandone el tratamiento. El tono alarmista y la jerga con una familia sin formación es lo que más derriba. Una buena sesión reconstruye la adhesión, y quien abandonó todavía atiende una llamada — una vez."), sug: { when: () => typeof Care !== "undefined" && Care.list().some((id) => Care.chanceFalta(Care.st(id)) > 0), do: L("Veja a adesão de cada um em Celular → Acompanhamento.", "Check each person's adherence in Phone → Follow-up.", "Mira la adhesión de cada uno en Celular → Seguimiento.") } },
    continuo: { t: L("Modo contínuo", "Endless mode", "Modo continuo"), x: L("Depois das 4 semanas a agenda segue sem fim: novos pacientes chegam por turma e por encaminhamentos pelo celular (o eixo Articulação aumenta a chance).", "After the 4 weeks the schedule goes on: new patients arrive in cohorts and by phone referrals (the Multidisciplinary axis raises the chance).", "Tras las 4 semanas la agenda sigue: nuevos pacientes llegan por tandas y por derivaciones por celular (el eje Articulación aumenta la probabilidad).") },
    carreira: { t: L("Carreira", "Career", "Carrera"), x: L("As reputações abrem sala de espera, recepção, equipe (que atende acompanhamentos e repassa parte do valor), aulas, artigos e congressos. Veja em Missões → Carreira.", "Reputations open the waiting room, reception, a team (that handles follow-ups and passes on part of the value), classes, articles and conferences. See Quests → Career.", "Las reputaciones abren sala de espera, recepción, equipo (que atiende seguimientos y cede parte del valor), clases, artículos y congresos. Mira Misiones → Carrera.") },
    eventos: { t: L("Acontecimentos e estresse", "Events and stress", "Acontecimientos y estrés"), x: L("Intercorrências e dilemas éticos chegam no celular (Mensagens). Cada escolha tem efeitos; o estresse sobe com crises e cai ao dormir, com supervisão e com autocuidado.", "Events and ethical dilemmas arrive on the phone (Messages). Each choice has effects; stress rises with crises and falls with sleep, supervision and self-care.", "Incidencias y dilemas éticos llegan por el celular (Mensajes). Cada elección tiene efectos; el estrés sube con crisis y baja al dormir, con supervisión y con autocuidado.") },
    risco: { t: L("Avaliação de risco", "Risk assessment", "Evaluación de riesgo"), x: L("Pergunte com clareza e sem julgamento. Nível 1: fatores de proteção; nível 2: Plano de Segurança; nível 3: decisão ética sobre o sigilo. Responda às mensagens de emergência do celular: ignorar soma negligência.", "Ask clearly and without judgment. Level 1: protective factors; level 2: Safety Plan; level 3: ethical decision about confidentiality. Answer emergency phone messages: ignoring adds negligence.", "Pregunta con claridad y sin juzgar. Nivel 1: factores de protección; nivel 2: Plan de Seguridad; nivel 3: decisión ética sobre el sigilo. Responde a los mensajes de emergencia del celular: ignorarlos suma negligencia.") },
    memorial: { t: L("Parque Memorial", "Memorial Park", "Parque Memorial"), x: L("Homenageie os pioneiros (+15 XP e verbetes no Manual), leia as lápides dos casos interrompidos e deixe flores (10 moedas, +20 de energia). Um lugar para cuidar de quem cuida.", "Pay tribute to the pioneers (+15 XP and Manual entries), read the tombstones of interrupted cases and leave flowers (10 coins, +20 energy). A place to care for the caregiver.", "Rinde homenaje a los pioneros (+15 XP y entradas del Manual), lee las lápidas de los casos interrumpidos y deja flores (10 monedas, +20 de energía). Un lugar para cuidar de quien cuida.") },
    aulas: { t: L("Aulas da academia", "Gym classes", "Clases del gimnasio"), x: L("As aulas têm horário marcado e cada uma é um joguinho de ritmo com a instrutora. Fazer a aula do dia recupera saúde e energia e alivia o estresse.", "Classes have set times and each is a rhythm mini-game with the instructor. Taking the day's class restores health and energy and eases stress.", "Las clases tienen horario y cada una es un minijuego de ritmo con la instructora. Hacer la clase del día recupera salud y energía y alivia el estrés."), sug: { when: () => true, do: L("Faça uma aula na academia (alongamento, yoga, pilates, dança ou boxe).", "Take a class at the gym (stretching, yoga, pilates, dance or boxing).", "Haz una clase en el gimnasio (estiramiento, yoga, pilates, baile o boxeo).") } },
    lojas: { screen: "shop", t: L("Lojas de móveis", "Furniture stores", "Tiendas de muebles"), x: L("O consultório já vem com o básico (tapete, diploma, abajur, cortina e os lenços) — tudo isso é trocável. Cada loja da cidade tem peças exclusivas que só aparecem depois de visitá-la. O guia Lojas da cidade mostra onde ficam.", "The office already comes with the basics (rug, diploma, lamp, curtain and the tissues) — all of it swappable. Each shop in town has exclusive pieces that only show up after you visit it. The City shops guide shows where they are.", "El consultorio ya viene con lo básico (alfombra, diploma, lámpara, cortina y los pañuelos), todo intercambiable. Cada tienda de la ciudad tiene piezas exclusivas que solo aparecen tras visitarla. La guía Tiendas de la ciudad muestra dónde están."), sug: { when: () => Object.keys(state.shopSeen || {}).length < 6, do: L("Visite uma loja de móveis nova (veja o guia Lojas da cidade).", "Visit a new furniture store (see the City shops guide).", "Visita una tienda de muebles nueva (mira la guía Tiendas de la ciudad).") } },
    deslocamento: { screen: "city", t: L("Andar, bicicleta e carro", "Walking, bike and car", "Caminar, bicicleta y coche"), x: L("Na cidade, use WASD/setas, o joystick ou toque no chão. O botão de deslocamento troca entre andar, bicicleta e carro: quem se mexe mais ganha Vida.", "In town, use WASD/arrows, the joystick or tap the ground. The travel button switches between walking, bike and car: moving more gives Health.", "En la ciudad, usa WASD/flechas, el joystick o toca el suelo. El botón de desplazamiento cambia entre caminar, bicicleta y coche: moverse más da Vida.") },
    figuras: { t: L("Figuras da história", "History figures", "Figuras de la historia"), x: L("Missões → Figuras dá uma pista de cada pessoa. Ache o lugar, converse e ganhe XP e moedas; achar uma abre pistas de outras.", "Quests → Figures gives a clue for each person. Find the place, talk and earn XP and coins; finding one opens clues to others.", "Misiones → Figuras da una pista de cada persona. Encuentra el lugar, conversa y gana XP y monedas; hallar una abre pistas de otras."), sug: { when: () => true, do: L("Leia uma pista em Missões → Figuras e vá procurar no mapa.", "Read a clue in Quests → Figures and go look on the map.", "Lee una pista en Misiones → Figuras y ve a buscar en el mapa.") } },
    atividades: { t: L("Atividades interativas", "Interactive activities", "Actividades interactivas"), x: L("Pescar, escavar conchas e brincar com o bichinho são joguinhos de verdade. Dá para desligar em Opções se preferir o botão simples.", "Fishing, digging for shells and playing with your pet are real mini-games. You can switch them off in Options if you prefer the simple button.", "Pescar, excavar conchas y jugar con la mascota son minijuegos de verdad. Puedes desactivarlos en Opciones si prefieres el botón simple.") },
    lugares: { t: L("Lugares de aprendizagem", "Learning places", "Lugares de aprendizaje"), x: L("Laboratório, museu, escola, fórum, CAPS, feira, parque e observatório têm cartões curtos com perguntinhas: acertar dá XP; alguns recuperam energia.", "The lab, museum, school, courthouse, CAPS, market, park and observatory have short cards with quick questions: right answers give XP; some restore energy.", "El laboratorio, museo, escuela, juzgado, CAPS, feria, parque y observatorio tienen tarjetas cortas con preguntas: acertar da XP; algunas recuperan energía.") },
    zoo: { t: L("Zoológico dos Biomas", "Biomes Zoo", "Zoológico de los Biomas"), x: L("Observe (1 vez por dia), alimente e doe ao projeto de cada animal para subir de nível. Observar os 2 animais de um bioma 3 vezes rende o selo do bioma; o Álbum mostra onde ver cada bioma no mapa.", "Watch (once a day), feed and donate to each animal's project to level up. Watching a biome's 2 animals 3 times each earns the biome seal; the Album shows where to see each biome on the map.", "Observa (1 vez al día), alimenta y dona al proyecto de cada animal para subir de nivel. Observar 3 veces a los 2 animales de un bioma da el sello del bioma; el Álbum muestra dónde ver cada bioma en el mapa."), sug: { when: () => true, do: L("Visite o Zoológico dos Biomas, na rua do lazer.", "Visit the Biomes Zoo on Leisure Boulevard.", "Visita el Zoológico de los Biomas en el Bulevar del Ocio.") } },
    vida: { t: L("Vida e estresse", "Health and stress", "Vida y estrés"), x: L("A Vida sobe com movimento e comida saudável e cai com sedentarismo. O estresse aparece no topo quando passa de 20%.", "Health rises with movement and healthy food and drops with a sedentary day. Stress shows at the top when it passes 20%.", "La Vida sube con movimiento y comida saludable y baja con sedentarismo. El estrés aparece arriba cuando pasa del 20%.") }
  };
  const MODAL = Object.fromEntries(Object.entries(TIPS).filter(([, v]) => v.modal).map(([k, v]) => [v.modal, k]));
  const SCREEN = Object.fromEntries(Object.entries(TIPS).filter(([, v]) => v.screen).map(([k, v]) => [v.screen, k]));
  // mostra a dica uma única vez (Tutor.topic cuida de "já vista" e das dicas desligadas)
  function fire(id) {
    const d = TIPS[id]; if (!d || typeof Tutor === "undefined" || !Tutor.topic) return false;
    return Tutor.topic(id, [{ key: id, title: d.t, text: d.x }]);
  }
  // envolve openModal e showScreen para disparar as dicas de quem abre modais/telas
  function watch() {
    if (window.__tipsWatch) return; window.__tipsWatch = true;
    const om = window.openModal; if (om) window.openModal = function (id) { const r = om.apply(this, arguments); if (MODAL[id]) setTimeout(() => fire(MODAL[id]), 350); return r; };
    const ss = window.showScreen; if (ss) window.showScreen = function (name) { const r = ss.apply(this, arguments); if (SCREEN[name]) setTimeout(() => fire(SCREEN[name]), 900); return r; };
  }
  // próximos passos sugeridos: só de coisas ainda não vistas
  function suggestions() {
    const seen = state.tuts || {};
    return Object.entries(TIPS).filter(([id, v]) => v.sug && !seen[id] && v.sug.when()).slice(0, 3).map(([id, v]) => ({ id, icon: "💡", text: pick(typeof v.sug.do === "function" ? v.sug.do() : v.sug.do), topic: pick(v.t) }));
  }
  return { TIPS, fire, watch, suggestions };
})();
window.Tips = Tips;
